#include <iostream>
#include <vector>
using namespace std;

int searchInsert(vector<int>& nums, int target) {
  // 左索引的初始值为 0
  int left = 0;
  // 右索引的初始值是数组中元素的数量
  int right = nums.size();
  // left + 1 >= right 将完成 while 循环
  while (left + 1 < right) {
    int mid = (right + left) / 2;

    if (nums[mid] == target) {
      // mid是目标索引
      return mid;
    } else if (nums[mid] < target) {
      // 在数组的左半部分搜索是没有意义的
      left = mid;
    } else {
      // 在数组的右半部分搜索没有意义
      right = mid;
    }
  }
  // left 可以是插入目标的索引
  if (nums[left] >= target) {
    return left;
  }
  // right 是插入目标的索引
  return right;
}

int main() {
  vector<int> nums = {1, 5, 8, 9, 11, 13, 15, 19, 21};

  cout << "Index of 9 is ---> "  << searchInsert(nums, 9) << endl;
  cout << "Index of 12 is ---> "  << searchInsert(nums, 12) << endl;
  cout << "Index of -4 is ---> "  << searchInsert(nums, -4) << endl;
  cout << "Index of 27 is ---> "  << searchInsert(nums, 27) << endl;

  return 0;
}

